import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { decisionSchema, type Decision } from "./decision.js";
import { taskListSchema, type TaskList } from "./task-list.js";

export type RespondDecisionTaskCompletedInput = {
  /**
   * The taskToken from the DecisionTask. taskToken is generated by the service and should be
   * treated as an opaque value. If the task is passed to another process, its taskToken must also
   * be passed. This enables it to provide its progress and respond with results.
   */
  taskToken: string;
  /**
   * The list of decisions (possibly empty) made by the decider while processing this decision task.
   * See the docs for the Decision structure for details.
   */
  decisions?: Decision[];
  /** User defined context to add to workflow execution. */
  executionContext?: string;
  taskList?: TaskList;
  /**
   * Specifies a timeout (in seconds) for the task list override. When this parameter is missing,
   * the task list override is permanent. This parameter makes it possible to temporarily override
   * the task list. If a decision task scheduled on the override task list is not started within the
   * timeout, the decision task will time out. Amazon SWF will revert the override and schedule a
   * new decision task to the original task list. If a decision task scheduled on the override task
   * list is started within the timeout, but not completed within the start-to-close timeout, Amazon
   * SWF will also revert the override
   */
  taskListScheduleToStartTimeout?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const respondDecisionTaskCompletedInputSchema: Schema<RespondDecisionTaskCompletedInput> =
  s.object<RespondDecisionTaskCompletedInput>(
    {
      taskToken: s.string(),
      decisions: s.optional(s.array(s.lazy(() => decisionSchema))),
      executionContext: s.optional(s.string()),
      taskList: s.optional(s.lazy(() => taskListSchema)),
      taskListScheduleToStartTimeout: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
